Lemma fg_walk T w f' : NTFW T w f' ->
  forall stx LSx ZB g bg (k : mstate -> mapinfo -> M T) bail c n Q,
  FGPRE stx LSx ZB g bg -> 48 - m_sizeclass (MR st0 g) <= Z.of_nat f' ->
  (forall st' mi, NPOST ZB st' mi -> apw w (k st' mi) c n Q) ->
